  select q.id, v.label, v.body, v.ok from q, (values ('A', 'Quan es fa en grups de més de deu persones', false), ('B', 'Sempre que hi hagi més de dues persones, només de nit', false), ('C', 'Quan es fa en grups de com a mínim tres persones', true), ('D', 'Només quan hi participen menors d''edat', false)) as v(label, body, ok)
)
