  select q.id, v.label, v.body, v.ok from q, (values ('A', 'La possibilitat que un treballador pateixi un dany determinat derivat del treball', true), ('B', 'El conjunt d''activitats adoptades per evitar o disminuir els riscos derivats del treball', false), ('C', 'Les malalties, patologies o lesions patides amb motiu o en ocasió del treball', false), ('D', 'Qualsevol característica del treball que pugui tenir una influència significativa en la generació de riscos', false)) as v(label, body, ok)
)
