insert into public.sources (title, url, kind, publisher, published_on) values ('Ley 7/1985, de 2 de abril, Reguladora de las Bases del Régimen Local (texto consolidado, BOE)', 'https://www.boe.es/buscar/act.php?id=BOE-A-1985-5392', 'boe'::public.source_kind, 'Agencia Estatal Boletín Oficial del Estado', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('gub-t03-regim-local', 'Tema 3. Llei 7/1985, reguladora de les bases del règim local: el municipi, disposicions comunes i personal') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('guardia-urbana-barcelona') and t.slug = 'gub-t03-regim-local' on conflict do nothing;
insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'ca', '[{"n":"1","title":"Les entitats locals (LBRL)"},{"n":"2","title":"El municipi: territori, població i padró"},{"n":"3","title":"Organització municipal: alcalde, Ple i Junta de Govern"},{"n":"4","title":"Competències municipals"},{"n":"5","title":"Règim de funcionament i de recursos"}]'::jsonb, '["Art. 11.1 Llei 7/1985: «El Municipio es la entidad local básica de la organización territorial del Estado.»","Art. 11.2 Llei 7/1985: «Son elementos del Municipio el territorio, la población y la organización.»","Art. 15 Llei 7/1985: «La condición de vecino se adquiere en el mismo momento de su inscripción en el Padrón.»","Art. 21.1 Llei 7/1985: «Ejercer la jefatura de la Policía Municipal.»","Art. 89 Llei 7/1985: «El personal al servicio de las entidades locales estará integrado por funcionarios de carrera, contratados en régimen de derecho laboral y personal eventual»","Art. 19.1 Llei 7/1985: «corresponde al ayuntamiento, integrado por el Alcalde y los Concejales»","Art. 3 Llei 7/1985: «Gozan, asimismo, de la condición de Entidades Locales: a) Las Comarcas u otras entidades que agrupen varios Municipios»","Art. 15 Llei 7/1985: «Quien viva en varios municipios deberá inscribirse únicamente en el que habite durante más tiempo al año.»","Art. 16.1 Llei 7/1985: «Las certificaciones que de dichos datos se expidan tendrán carácter de documento público y fehaciente para todos los efectos administrativos.»","Art. 20.1 Llei 7/1985: «El Alcalde, los Tenientes de Alcalde y el Pleno existen en todos los ayuntamientos.»","Art. 20.1 Llei 7/1985: «La Junta de Gobierno Local existe en todos los municipios con población superior a 5.000 habitantes»","Art. 23.1 Llei 7/1985: «La Junta de Gobierno Local se integra por el Alcalde y un número de Concejales no superior al tercio del número legal de los mismos»","Art. 23.3 Llei 7/1985: «Los Tenientes de Alcalde sustituyen, por el orden de su nombramiento y en los casos de vacante, ausencia o enfermedad, al Alcalde»","Art. 26.1 Llei 7/1985: «En los Municipios con población superior a 20.000 habitantes, además: protección civil»","Art. 84.1 Llei 7/1985: «Las Entidades locales podrán intervenir la actividad de los ciudadanos a través de los siguientes medios: a) Ordenanzas y bandos.»","Art. 26.1 Llei 7/1985: «En todos los Municipios: alumbrado público, cementerio, recogida de residuos, limpieza viaria»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1985-5392'), 'https://www.boe.es/buscar/act.php?id=BOE-A-1985-5392', null, null, null, null
