insert into public.sources (title, url, kind, publisher, published_on) values ('Real Decreto Legislativo 5/2015, de 30 de octubre, texto refundido de la Ley del Estatuto Básico del Empleado Público (texto consolidado, BOE)', 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719', 'boe'::public.source_kind, 'Agencia Estatal Boletín Oficial del Estado', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('gub-t06-ebep', 'Tema 6. L''Estatut bàsic de l''empleat públic: drets i deures, codi de conducta i situacions') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('guardia-urbana-barcelona') and t.slug = 'gub-t06-ebep' on conflict do nothing;
insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'ca', '[{"n":"1","title":"Classes de personal al servei de les administracions públiques"},{"n":"2","title":"Drets i deures; codi de conducta"},{"n":"3","title":"Accés a l''ocupació pública i adquisició de la condició de funcionari"},{"n":"4","title":"Situacions administratives"},{"n":"5","title":"Règim disciplinari: faltes i sancions"}]'::jsonb, '["Art. 85.1 TREBEP: «a) Servicio activo. b) Servicios especiales. c) Servicio en otras Administraciones Públicas. d) Excedencia. e) Suspensión de funciones.»","Art. 95.1 TREBEP: «Las faltas disciplinarias pueden ser muy graves, graves y leves.»","Art. 15 TREBEP: «c) Al ejercicio de la huelga, con la garantía del mantenimiento de los servicios esenciales de la comunidad.»","Art. 14 TREBEP: «a) A la inamovilidad en la condición de funcionario de carrera.»","Art. 54.1 TREBEP: «Tratarán con atención y respeto a los ciudadanos, a sus superiores y a los restantes empleados públicos.»","Art. 56.1 TREBEP: «c) Tener cumplidos dieciséis años y no exceder, en su caso, de la edad máxima de jubilación forzosa.»","Art. 62.1 TREBEP: «d) Toma de posesión dentro del plazo que se establezca.»","Art. 63 TREBEP: «d) La sanción disciplinaria de separación del servicio que tuviere carácter firme.»","Art. 66 TREBEP: «produce la pérdida de la condición de funcionario respecto a todos los empleos o cargos que tuviere»","Art. 52 TREBEP: «transparencia, ejemplaridad, austeridad, accesibilidad, eficacia, honradez»","Art. 54.3 TREBEP: «Obedecerán las instrucciones y órdenes profesionales de los superiores, salvo que constituyan una infracción manifiesta del ordenamiento jurídico»","Art. 54.6 TREBEP: «Se rechazará cualquier regalo, favor o servicio en condiciones ventajosas que vaya más allá de los usos habituales, sociales y de cortesía»","Art. 89.1 TREBEP: «c) Excedencia por cuidado de familiares. d) Excedencia por razón de violencia de género o de violencia sexual.»","Art. 89.2 TREBEP: «durante un periodo mínimo de cinco años inmediatamente anteriores»","Art. 98.1 TREBEP: «La imposición de sanciones por faltas leves se llevará a cabo por procedimiento sumario con audiencia al interesado.»","Art. 90.1 TREBEP: «La suspensión determinará la pérdida del puesto de trabajo cuando exceda de seis meses.»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719'), 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-11719', null, null, null, null
  from public.topics t where t.slug = 'gub-t06-ebep'
