insert into public.sources (title, url, kind, publisher, published_on) values ('Ley 31/1995, de 8 de noviembre, de prevención de Riesgos Laborales (texto consolidado, BOE)', 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-24292', 'boe'::public.source_kind, 'Agencia Estatal Boletín Oficial del Estado', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('gub-t07-prevencio-riscos-laborals', 'Tema 7. Llei 31/1995, de prevenció de riscos laborals') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('guardia-urbana-barcelona') and t.slug = 'gub-t07-prevencio-riscos-laborals' on conflict do nothing;
insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'ca', '[{"n":"1","title":"Objecte i àmbit de la Llei de prevenció de riscos laborals"},{"n":"2","title":"Definicions bàsiques (risc laboral, dany, prevenció)"},{"n":"3","title":"Drets i obligacions de l''empresari i dels treballadors"},{"n":"4","title":"Serveis de prevenció i delegats de prevenció"},{"n":"5","title":"Particularitats en l''àmbit de les policies"}]'::jsonb, '["Art. 4.2 Llei 31/1995: «Se entenderá como «riesgo laboral» la posibilidad de que un trabajador sufra un determinado daño derivado del trabajo.»","Art. 4.1 Llei 31/1995: «Se entenderá por «prevención» el conjunto de actividades o medidas adoptadas o previstas en todas las fases de actividad de la empresa con el fin de evitar o disminuir los riesgos derivados del trabajo.»","Art. 14.1 Llei 31/1995: «Los trabajadores tienen derecho a una protección eficaz en materia de seguridad y salud en el trabajo.»","Art. 15.1 Llei 31/1995: «a) Evitar los riesgos. b) Evaluar los riesgos que no se puedan evitar. c) Combatir los riesgos en su origen.»","Art. 38.1 Llei 31/1995: «El Comité de Seguridad y Salud es el órgano paritario y colegiado de participación destinado a la consulta regular y periódica de las actuaciones de la empresa en materia de prevención de riesgos.»","Art. 35.1 Llei 31/1995: «Los Delegados de Prevención son los representantes de los trabajadores con funciones específicas en materia de prevención de riesgos en el trabajo.»","Art. 4.2 Llei 31/1995: «Para calificar un riesgo desde el punto de vista de su gravedad, se valorarán conjuntamente la probabilidad de que se produzca el daño y la severidad del mismo.»","Art. 4.4 Llei 31/1995: «Se entenderá como «riesgo laboral grave e inminente» aquel que resulte probable racionalmente que se materialice en un futuro inmediato»","Art. 15.1 Llei 31/1995: «h) Adoptar medidas que antepongan la protección colectiva a la individual.»","Art. 21.1 Llei 31/1995: «los trabajadores puedan interrumpir su actividad y, si fuera necesario, abandonar de inmediato el lugar de trabajo»","Art. 22.1 Llei 31/1995: «Esta vigilancia sólo podrá llevarse a cabo cuando el trabajador preste su consentimiento.»","Art. 22.2 Llei 31/1995: «Las medidas de vigilancia y control de la salud de los trabajadores se llevarán a cabo respetando siempre el derecho a la intimidad y a la dignidad de la persona del trabajador»","Art. 29.1 Llei 31/1995: «Corresponde a cada trabajador velar, según sus posibilidades y mediante el cumplimiento de las medidas de prevención que en cada caso sean adoptadas, por su propia seguridad y salud en el trabajo y por la de aquellas otras personas a las que pueda afectar su actividad profesional»","Art. 29.3 Llei 31/1995: «El incumplimiento por los trabajadores de las obligaciones en materia de prevención de riesgos a que se refieren los apartados anteriores tendrá la consideración de incumplimiento laboral»","Art. 38.2 Llei 31/1995: «Se constituirá un Comité de Seguridad y Salud en todas las empresas o centros de trabajo que cuenten con 50 o más trabajadores.»","Art. 38.3 Llei 31/1995: «El Comité de Seguridad y Salud se reunirá trimestralmente y siempre que lo solicite alguna de las representaciones en el mismo.»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-24292'), 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-24292', null, null, null, null
  from public.topics t where t.slug = 'gub-t07-prevencio-riscos-laborals'
on conflict (topic_id, locale) do update
   set outline = excluded.outline, key_ideas = excluded.key_ideas, glossary = excluded.glossary,
       amendments = excluded.amendments, source_id = excluded.source_id, source_url = excluded.source_url,
       page_from = excluded.page_from, page_to = excluded.page_to, key_ideas_page = excluded.key_ideas_page
 where (n.outline, n.key_ideas, n.glossary, n.amendments)
       is distinct from (excluded.outline, excluded.key_ideas, excluded.glossary, excluded.amendments);
insert into public.sources (title, url, kind, publisher, published_on) values ('Ley Orgánica 3/2007, de 22 de marzo, para la igualdad efectiva de mujeres y hombres (texto consolidado, BOE)', 'https://www.boe.es/buscar/act.php?id=BOE-A-2007-6115', 'boe'::public.source_kind, 'Agencia Estatal Boletín Oficial del Estado', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('gub-t08-igualtat', 'Tema 8. Igualtat de dones i homes: LO 3/2007 i Llei 17/2015') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('guardia-urbana-barcelona') and t.slug = 'gub-t08-igualtat' on conflict do nothing;
insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'ca', '[{"n":"1","title":"Igualtat efectiva de dones i homes (LO 3/2007)"},{"n":"2","title":"Llei 17/2015 d''igualtat efectiva de Catalunya"},{"n":"3","title":"Discriminació directa i indirecta, assetjament"},{"n":"4","title":"Plans d''igualtat i mesures en l''ocupació pública"},{"n":"5","title":"Igualtat i accés a les policies locals (Llei 16/1991, DA 8a)"}]'::jsonb, '["Art. 6.1 LO 3/2007: «Se considera discriminación directa por razón de sexo la situación en que se encuentra una persona que sea, haya sido o pudiera ser tratada, en atención a su sexo, de manera menos favorable que otra en situación comparable.»","Art. 8 LO 3/2007: «Constituye discriminación directa por razón de sexo todo trato desfavorable a las mujeres relacionado con el embarazo o la maternidad.»","Art. 1.1 LO 3/2007: «Las mujeres y los hombres son iguales en dignidad humana, e iguales en derechos y deberes.»","Art. 7.1 LO 3/2007: «constituye acoso sexual cualquier comportamiento, verbal o físico, de naturaleza sexual que tenga el propósito o produzca el efecto de atentar contra la dignidad de una persona»","DA octava.2 Llei 16/1991: «no puede ser superior al 40 % de las plazas convocadas ni inferior al porcentaje que sea establecido por el plan de igualdad de cada ayuntamiento»","Art. 3 LO 3/2007: «El principio de igualdad de trato entre mujeres y hombres supone la ausencia de toda discriminación, directa o indirecta, por razón de sexo»","Art. 6.2 LO 3/2007: «Se considera discriminación indirecta por razón de sexo la situación en que una disposición, criterio o práctica aparentemente neutros pone a personas de un sexo en desventaja particular»","Art. 3 LO 3/2007: «y, especialmente, las derivadas de la maternidad, la asunción de obligaciones familiares y el estado civil»","Art. 11.1 LO 3/2007: «Tales medidas, que serán aplicables en tanto subsistan dichas situaciones, habrán de ser razonables y proporcionadas en relación con el objetivo perseguido en cada caso.»","Art. 45.2 LO 3/2007: «En el caso de las empresas de cincuenta o más trabajadores, las medidas de igualdad a que se refiere el apartado anterior deberán dirigirse a la elaboración y aplicación de un plan de igualdad»","Art. 46.1 LO 3/2007: «Los planes de igualdad de las empresas son un conjunto ordenado de medidas, adoptadas después de realizar un diagnóstico de situación»","DA primera LO 3/2007: «las personas de cada sexo no superen el sesenta por ciento ni sean menos del cuarenta por ciento»","Art. 1.1 Llei 17/2015: «El objeto de la presente ley es establecer y regular los mecanismos y recursos para hacer efectivo el derecho a la igualdad y a la no discriminación por razón de sexo en todos los ámbitos, etapas y circunstancias de la vida.»","Art. 3 Llei 17/2015: «Primero.–Transversalidad de la perspectiva de género y de las políticas de igualdad de género»","Art. 3 Llei 17/2015: «En cumplimiento del principio de perspectiva de género a que se refiere el artículo 41 del Estatuto de autonomía»","DA octava.2 Llei 16/1991: «el porcentaje mínimo no puede ser inferior al 25 % de las plazas convocadas, siempre que se convoquen más de tres»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2007-6115'), 'https://www.boe.es/buscar/act.php?id=BOE-A-2007-6115', null, null, null, 'Otras normas citadas: Llei 16/1991 (https://www.boe.es/buscar/act.php?id=BOE-A-1991-20343), Llei 17/2015 (https://www.boe.es/buscar/act.php?id=BOE-A-2015-9676)'
  from public.topics t where t.slug = 'gub-t08-igualtat'
on conflict (topic_id, locale) do update
   set outline = excluded.outline, key_ideas = excluded.key_ideas, glossary = excluded.glossary,
       amendments = excluded.amendments, source_id = excluded.source_id, source_url = excluded.source_url,
       page_from = excluded.page_from, page_to = excluded.page_to, key_ideas_page = excluded.key_ideas_page
 where (n.outline, n.key_ideas, n.glossary, n.amendments)
       is distinct from (excluded.outline, excluded.key_ideas, excluded.glossary, excluded.amendments);
insert into public.sources (title, url, kind, publisher, published_on) values ('Ley 22/1998, de 30 de diciembre, de la Carta Municipal de Barcelona (texto consolidado, BOE)', 'https://www.boe.es/buscar/act.php?id=BOE-A-1999-2518', 'boe'::public.source_kind, 'Agencia Estatal Boletín Oficial del Estado', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('gub-t09-carta-municipal', 'Tema 9. Llei 22/1998, Carta municipal de Barcelona') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('guardia-urbana-barcelona') and t.slug = 'gub-t09-carta-municipal' on conflict do nothing;
insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'ca', '[{"n":"1","title":"La Carta municipal de Barcelona: principis"},{"n":"2","title":"Organització: Consell Municipal, alcalde i Comissió de Govern"},{"n":"3","title":"Districtes i participació ciutadana"},{"n":"4","title":"Competències municipals en seguretat i convivència"},{"n":"5","title":"La Guàrdia Urbana a la Carta municipal"}]'::jsonb, '["Art. 133 Carta municipal: «La Guardia Urbana de Barcelona actúa como policía de autoridad, policía de seguridad y asistencial y policía judicial»","Art. 10.1 Carta municipal: «El Consejo Municipal es el órgano de máxima representación política de los ciudadanos en el gobierno de la ciudad.»","Art. 13.1 Carta municipal: «Ejercer la dirección superior de todo el personal de la Administración Municipal y la Jefatura de la Policía Municipal.»","Art. 135 Carta municipal: «Instruir atestados por accidentes de circulación dentro del término municipal.»","Art. 94.1 Carta municipal: «La sanción por infracciones a normas de circulación cometidas en vías urbanas corresponde al Alcalde o Alcaldesa.»","Art. 9 Carta municipal: «a) El Consejo Municipal. b) El Alcalde o Alcaldesa. c) La Comisión de Gobierno.»","Art. 8 Carta municipal: «El Gobierno Municipal actúa de acuerdo con los principios de eficacia, jerarquía, descentralización, desconcentración y coordinación.»","Art. 11.1 Carta municipal: «d) Aprobar el escudo, la bandera y los demás símbolos distintivos de la ciudad.»","Art. 11.1 Carta municipal: «b) Aprobar el Código Ético de actuación de todo el personal al servicio del municipio.»","Art. 21.3 Carta municipal: «El presupuesto municipal debe garantizar que cada año el 15 por 100 de sus recursos ordinarios, como mínimo, sean gestionados por los distritos.»","Art. 22.1 Carta municipal: «El Presidente o Presidenta del Consejo de Distrito es nombrado y separado por el Alcalde o Alcaldesa de entre los Concejales, a propuesta del Consejo de Distrito»","Art. 128.2 Carta municipal: «Estas competencias y funciones municipales en materia de seguridad son desarrolladas por la Guardia Urbana de Barcelona»","Art. 132.1 Carta municipal: «El Alcalde o Alcaldesa de Barcelona tiene la condición de autoridad competente en materia de seguridad»","Art. 134 Carta municipal: «vela, a partir de las instrucciones generales y las órdenes emanadas de las autoridades municipales, especialmente del Alcalde o Alcaldesa, por el cumplimiento de las ordenanzas, bandos y otras disposiciones municipales»","Art. 96 Carta municipal: «El Ayuntamiento de Barcelona dispone de personal auxiliar de la Guardia Urbana para controlar la utilización adecuada de los aparcamientos en la vía pública»","Art. 131.1 Carta municipal: «Elaborar las políticas y planes de seguridad ciudadana y de prevención del delito, dentro del ámbito municipal.»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1999-2518'), 'https://www.boe.es/buscar/act.php?id=BOE-A-1999-2518', null, null, null, null
  from public.topics t where t.slug = 'gub-t09-carta-municipal'
