insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'ca', '[{"n":"1","title":"Règim especial del municipi de Barcelona (Llei 1/2006)"},{"n":"2","title":"Organització del govern municipal"},{"n":"3","title":"Competències en seguretat ciutadana i trànsit"},{"n":"4","title":"Junta Local de Seguretat de Barcelona"},{"n":"5","title":"Relacions amb l''Estat i la Generalitat"}]'::jsonb, '["Art. 34 Llei 1/2006: «La Guardia Urbana de Barcelona, bajo la dependencia jerárquica del Alcalde de Barcelona, actúa como policía administrativa, policía de seguridad y asistencial y policía judicial»","Art. 1.1 Llei 1/2006: «goza de las especialidades que le reconoce la presente Ley en materias de competencia estatal»","Art. 1.2 Llei 1/2006: «El régimen especial del municipio de Barcelona se integra por lo dispuesto en la presente Ley y en la Ley del Parlamento de Cataluña 22/1998, de 30 de diciembre, de la Carta Municipal de Barcelona»","Art. 28 Llei 1/2006: «Los gastos que se originen como consecuencia de la inmovilización del vehículo serán por cuenta del titular»","Art. 24.1 Llei 1/2006: «El Ayuntamiento podrá nombrar personal auxiliar para controlar la adecuada utilización de las paradas y estacionamientos en la vía pública»","Art. 3 Llei 1/2006: «El Ayuntamiento de Barcelona podrá promover toda clase de actividades y prestar todos los servicios públicos que contribuyan a satisfacer las necesidades de los ciudadanos que no estén expresamente atribuidos a otras administraciones públicas.»","Art. 5 Llei 1/2006: «Se crea una Comisión, integrada por representantes del Estado, la Generalidad de Cataluña y el Ayuntamiento de Barcelona»","Art. 19.2 Llei 1/2006: «La realización de las pruebas, reglamentariamente establecidas, para determinar el grado de intoxicación alcohólica, por estupefacientes, psicotrópicos o estimulantes, de los conductores»","Art. 22.2 Llei 1/2006: «Los agentes de la autoridad podrán ordenar la retirada de vehículos de forma remota mediante la constatación de que concurren los supuestos previstos en la normativa aplicable, a través de fotografías, filmación digital u otros medios tecnológicos.»","Art. 22.4 Llei 1/2006: «Los agentes de la autoridad podrán proceder a la retirada y depósito de un vehículo en los casos en que se compruebe que circula sin estar provisto del correspondiente seguro obligatorio de vehículos»","Art. 21.3 Llei 1/2006: «Los agentes de la autoridad podrán inmovilizar un vehículo si comprueban que no ha sido solicitada la renovación de su permiso de circulación, cuando varíe la titularidad de aquél»","Art. 25.2 Llei 1/2006: «Dichos funcionarios no se integrarán en las Fuerzas y Cuerpos de Seguridad y, en el ejercicio de sus funciones, tendrán la consideración de agentes de la autoridad subordinados a los miembros de la Guardia urbana»","Art. 30.2 Llei 1/2006: «como la demanda o adquisición de tales servicios o bienes»","Art. 33 Llei 1/2006: «El Alcalde informará anualmente al Pleno acerca del seguimiento de los acuerdos de la Junta Local de Seguridad.»","Art. 30.3 Llei 1/2006: «se podrá sustituir la sanción económica por trabajos en beneficio de la comunidad, la asistencia obligatoria a cursos de formación, a sesiones individualizadas o cualquier otra medida alternativa»","Art. 31.2 Llei 1/2006: «un Fiscal designado por el Fiscal jefe del Tribunal Superior de Justicia»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2006-4583'), 'https://www.boe.es/buscar/act.php?id=BOE-A-2006-4583', null, null, null, null
  from public.topics t where t.slug = 'gub-t10-regim-especial-barcelona'
