insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'ca', '[{"n":"1","title":"Els districtes de Barcelona: divisió territorial"},{"n":"2","title":"Normes reguladores del funcionament dels districtes"},{"n":"3","title":"Òrgans de govern del districte"},{"n":"4","title":"Participació ciutadana als districtes"},{"n":"5","title":"Coneixement de la ciutat: barris i districtes"}]'::jsonb, '["Art. 2 Normes reguladores del funcionament dels districtes: «Els districtes de Barcelona són: Ciutat Vella, Eixample, Sants-Montjuïc, Les Corts, Sarrià-Sant Gervasi, Gràcia, Horta-Guinardó, Nou Barris, Sant Andreu i Sant Martí»","Art. 2 Normes reguladores del funcionament dels districtes: «establerts per acord del Consell Plenari de 18 de gener de 1984»","Art. 1 Normes reguladores del funcionament dels districtes: «Els districtes són òrgans territorials per a la desconcentració de la gestió i la descentralització de la participació ciutadana»","Art. 2 Normes reguladores del funcionament dels districtes: «Correspon al Consell Municipal acordar l''establiment de districtes, i també establir-ne el nombre i els límits territorials, l''organització i les funcions.»","Art. 8 Normes reguladores del funcionament dels districtes: «El Consell del Districte és l''òrgan de representació i participació col·lectiva del districte.»","Art. 1 Normes reguladores del funcionament dels districtes: «L''actuació dels districtes s''ha d''ajustar als principis d''unitat de govern, eficàcia, coordinació i solidaritat.»","Art. 5 Normes reguladores del funcionament dels districtes: «El pressupost municipal haurà de garantir que cada any el 15% dels seus recursos ordinaris, com a mínim, siguin gestionats pels districtes.»","Art. 7 Normes reguladores del funcionament dels districtes: «Els districtes constitueixen una estructura orgànica integrada pels òrgans següents: El Consell del Districte. El President/a del Consell del Districte. El Regidor/a del Districte. La Comissió de Govern del Districte.»","Art. 8 Normes reguladores del funcionament dels districtes: «* Fins a 90.000 residents: 15 Consellers/es.»","Art. 8 Normes reguladores del funcionament dels districtes: «* Més de 240.000 residents: 23 Consellers/ es.»","Art. 8 Normes reguladores del funcionament dels districtes: «Els Regidors/res de Districte i els Regidor/ res adscrits actuaran amb veu i sense vot.»","Art. 12 Normes reguladores del funcionament dels districtes: «El President o Presidenta del Consell del Districte només podrà exercir el seu dret a vot en cas d''empat.»","Art. 9 Normes reguladores del funcionament dels districtes: «Els Consells de Districte s''hauran de constituir com a màxim tres mesos després de la constitució del Consistori.»","Art. 8 Normes reguladores del funcionament dels districtes: «El/la cap de la Secretaria del districte actuarà de secretari.»","Art. 13 Normes reguladores del funcionament dels districtes: «Correspon al President/a del Consell de Districte: Representar l''Ajuntament i el districte en la demarcació del districte, sense perjudici de la funció representativa general de l''alcalde.»","Art. 2 Normes reguladores del funcionament dels districtes: «Els límits podran ser modificats pel mateix Consell municipal, a proposta de la Comissió de Govern o dels districtes afectats i amb informe preceptiu dels Consells de Districte respectius.»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, (select id from public.sources where url = 'https://ajuntament.barcelona.cat/norma-portal-juridic/ca/vid/845052020'), 'https://ajuntament.barcelona.cat/norma-portal-juridic/ca/vid/845052020', null, null, null, null
