insert into public.sources (title, url, kind, publisher, published_on) values ('Ley 4/1997, de 20 de mayo, de protección civil de Cataluña (texto consolidado, BOE)', 'https://www.boe.es/buscar/act.php?id=BOE-A-1997-14409', 'boe'::public.source_kind, 'Agencia Estatal Boletín Oficial del Estado', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('gub-t13-proteccio-civil', 'Tema 13. Llei 4/1997, de protecció civil de Catalunya') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('guardia-urbana-barcelona') and t.slug = 'gub-t13-proteccio-civil' on conflict do nothing;
insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'ca', '[{"n":"1","title":"Objecte i principis de la Llei de protecció civil de Catalunya"},{"n":"2","title":"Deures dels ciutadans i de les administracions"},{"n":"3","title":"Plans de protecció civil: tipus i contingut"},{"n":"4","title":"Activació dels plans i direcció de l''emergència"},{"n":"5","title":"Competències municipals en protecció civil"}]'::jsonb, '["Art. 15.1 Llei 4/1997: «Los planes de protección civil pueden ser territoriales, especiales y de autoprotección.»","Art. 40.1 Llei 4/1997: «a) El Alcalde o Alcaldesa, en el ámbito municipal.»","Art. 1.1 Llei 4/1997: «comprende las acciones destinadas a la protección de las personas, los bienes y el medio ambiente ante situaciones de grave riesgo colectivo, catástrofes y calamidades públicas»","Art. 47.1 Llei 4/1997: «Los municipios son las entidades básicas de la protección civil en Cataluña»","Art. 45.1 Llei 4/1997: «El Centro de Coordinación Operativa de Cataluña (CECAT) es el centro superior de coordinación e información de la estructura de protección civil de Cataluña»","Art. 6.3 Llei 4/1997: «El deber de colaboración se extiende a los simulacros que organicen las autoridades de protección civil.»","Art. 9 Llei 4/1997: «a) Evacuar o alejar a las personas de los sitios de peligro. b) Recomendar el confinamiento de personas en sus domicilios o en sitios seguros»","Art. 10.1 Llei 4/1997: «La prestación de estos servicios es obligatoria y no da lugar a indemnización por esta causa.»","Art. 17.1 Llei 4/1997: «Los niveles básicos de planificación son el conjunto de Cataluña y los municipios.»","Art. 17.2 Llei 4/1997: «Los municipios con una población superior a los veinte mil habitantes»","Art. 18.2 Llei 4/1997: «las emergencias producidas por riesgos de inundaciones, sísmicos, químicos, de transporte de mercancías peligrosas, incendios forestales y volcánicos»","Art. 18.2 Llei 4/1997: «Los planes especiales se declaran de interés de Cataluña.»","Art. 16.1 Llei 4/1997: «El Plan de protección civil de Cataluña debe ser aprobado por el Gobierno a propuesta del Consejero o Consejera de Gobernación, previo informe de la Comisión de Protección Civil de Cataluña.»","Art. 48.1 Llei 4/1997: «El Alcalde o Alcaldesa es la autoridad local superior de protección civil»","Art. 7.1 Llei 4/1997: «están obligados a la adopción de medidas de autoprotección y a mantener los medios personales y materiales necesarios para hacer frente a situaciones de riesgo y emergencia»","Art. 51.1 Llei 4/1997: «Los municipios con más de cincuenta mil habitantes»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1997-14409'), 'https://www.boe.es/buscar/act.php?id=BOE-A-1997-14409', null, null, null, null
