insert into public.sources (title, url, kind, publisher, published_on) values ('Ordenança de modificació de l''Ordenança de mesures per fomentar i garantir la convivència ciutadana a l''espai públic de Barcelona (aprovada pel Consell Municipal el 19/12/2025, en vigor el 15/02/2026). Extracte literal dels articles modificats', 'https://ajuntament.barcelona.cat/transparencia/ca/modificacio-ordenanca-convivencia', 'web_oficial'::public.source_kind, 'Ajuntament de Barcelona · Portal de Transparència', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('gub-t14-ordenanca-convivencia', 'Tema 14. Ordenança de mesures per fomentar i garantir la convivència ciutadana a l''espai públic') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('guardia-urbana-barcelona') and t.slug = 'gub-t14-ordenanca-convivencia' on conflict do nothing;
insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'ca', '[{"n":"1","title":"Objecte i principis de l''Ordenança de convivència"},{"n":"2","title":"Normes de conducta a l''espai públic"},{"n":"3","title":"Degradació visual: grafits i pintades"},{"n":"4","title":"Usos impropis de l''espai públic i consum de begudes"},{"n":"5","title":"Règim sancionador i mesures de policia"}]'::jsonb, '["Art. 4.1 Ordenança de convivència: «Aquesta Ordenança s''aplica a totes les persones que són a la ciutat de Barcelona.»","Art. 21 Ordenança de convivència: «la realització de les conductes descrites en l''article 20 té la consideració d''infracció lleu i és sancionada amb multa de 100 EUR fins a 600 EUR»","Art. 23.1 Ordenança de convivència: «es prohibeix llençar o abandonar a l''espai públic qualsevol deixalla sòlida de format petit, com ara papers, embolcalls, mocadors, xiclets, vasos, envasos»","Art. 8 Ordenança de convivència: «correspon a l''alcalde o alcaldessa establir i dirigir l''organització municipal executiva en matèria de convivència»","Art. 7 Ordenança de convivència: «El català és la llengua d''ús normal i oficial de l''Ajuntament de Barcelona i ha de ser emprat en les campanyes informatives de comunicació»","Art. 6 bis Ordenança de convivència: «Tothom ha de tenir una conducta responsable en l''ús de l''espai públic i ha de contribuir a què el seu ús comú general sigui amable, accessible i respectuós amb els drets de la ciutadania de Barcelona.»","Art. 23.2 Ordenança de convivència: «llevat que es faci entre les 22:00 hores i les 07:00 hores de l''endemà»","Art. 24 Ordenança de convivència: «els fets descrits en l''article 23 són constitutius d''una infracció lleu, sancionats amb una multa de fins a 750 EUR»","Art. 16 bis Ordenança de convivència: «c) Realitzar tocaments o fregaments amb connotacions sexuals a d''altres persones, inclosos els simuladament accidentals.»","Art. 17.3 Ordenança de convivència: «la realització de les conductes descrites a l''article 16 bis té la consideració d''infracció lleu, sancionada amb una multa de 100 EUR fins a 600 EUR»","Art. 17.2 Ordenança de convivència: «tenen la consideració d''infraccions molt greus, sancionades amb multa de 1.500,01 EUR fins a 3.000 EUR, les conductes descrites en els apartats 2 i 3 de l''article 16»","Art. 17.4 Ordenança de convivència: «la comissió de la infracció s''ha d''imputar a totes les persones membres d''aquests grups que es trobin al lloc dels fets i participin activament en la seva realització»","Art. 46.2 Ordenança de convivència: «c) Es realitzi en grups de com a mínim tres persones»","Art. 47.1 Ordenança de convivència: «La conducta descrita a l''apartat 2 de l''article 46 és constitutiva d''una infracció lleu, sancionada amb multa de 100 EUR fins a 600 EUR.»","Art. 44.1 Ordenança de convivència: «La conducta descrita en l''apartat 1 de l''article 43 constitueix una infracció lleu, sancionada amb multa de fins a 300 EUR»","Art. 43.2 Ordenança de convivència: «c) Quan es realitzi en carrers de 4 metres o menys d''amplada.»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, (select id from public.sources where url = 'https://ajuntament.barcelona.cat/transparencia/ca/modificacio-ordenanca-convivencia'), 'https://ajuntament.barcelona.cat/transparencia/ca/modificacio-ordenanca-convivencia', null, null, null, null
  from public.topics t where t.slug = 'gub-t14-ordenanca-convivencia'
