insert into public.topics (slug, title) values ('gub-t15-ordenanca-us-vies', 'Tema 15. Ordenança sobre l''ús de les vies i l''espai públic de Barcelona') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('guardia-urbana-barcelona') and t.slug = 'gub-t15-ordenanca-us-vies' on conflict do nothing;
insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'ca', '[{"n":"1","title":"Ús comú general i especial de les vies públiques"},{"n":"2","title":"Llicències d''ocupació de la via pública"},{"n":"3","title":"Denominació de vies i prohibició de fumar a les platges"},{"n":"4","title":"Prohibicions d''ús i restriccions"},{"n":"5","title":"Règim sancionador"}]'::jsonb, '["Art. 1 Ordenança d''ús de les vies: «es regeixen per l''Ordenança de terrasses»","Art. 8 Ordenança d''ús de les vies: «L''ús comú general de les vies públiques és aquell que es fa d''acord amb la naturalesa dels espais o instal·lacions corresponents, essencialment la circulació o l''estada de les persones.»","Art. 29 Ordenança d''ús de les vies: «No es pot portar a terme un ús comú especial de les vies, espais o instal·lacions públiques sense obtenir prèviament llicència municipal.»","Art. 10 Ordenança d''ús de les vies: «Es prohibeix de consumir productes de tabac a les platges de Barcelona.»","Art. 3 Ordenança d''ús de les vies: «Correspon a l''Alcalde atribuir la denominació de les vies públiques i la numeració dels immobles»","Art. 4 Ordenança d''ús de les vies: «Correspon a l''Ajuntament portar a terme els treballs de reparació i conservació de les vies públiques que són de titularitat municipal»","Art. 10 Ordenança d''ús de les vies: «S''exceptua d''aquesta prohibició el consum fet en l''espai ocupat per les \"guinguetes-bar\" de temporada instal·lades a la sorra.»","Art. 2 Ordenança d''ús de les vies: «Ordinàriament, els usos comuns de caràcter general són preferents a la resta d''usos.»","Art. 5 Ordenança d''ús de les vies: «Els serveis municipals retiraran els objectes abandonats o dipositats a la via pública sense llicència quan no sigui possible indentificar o localitzar en el mateix moment el seu propietari o responsable o quan aquest es negui a retirar l''objecte.»","Art. 6 Ordenança d''ús de les vies: «L''Alcalde comunicarà a l''autoritat governativa la proposta de variació en el recorregut o l''emplaçament de les manifestacions»","Art. 9 Ordenança d''ús de les vies: «Instal·lació de taquilles de venda de bitllets per a espectacles.»","Art. 17 Ordenança d''ús de les vies: «Les persones que no respectin les normes de comportament a la via pública seran requerides per tal que cessin en la seva actitud i, en cas de resistència, podran ser desallotjades.»","Art. 27 Ordenança d''ús de les vies: «L''ús comú especial és el que, sense excloure de forma permanent altres usos, sotmet la via o espai públic afectat a una especial intensitat o perillositat»","Art. 28 Ordenança d''ús de les vies: «L''exercici d''indústries o activitats professionals a la via pública que impliquin un ús intensiu de l''espai públic, com el rodatge de pel·lícules, els autotaxis i automòbils de lloguer.»","Art. 7 Ordenança d''ús de les vies: «L''Alcalde pot dictar les ordres singulars i les disposicions especials que s''escaiguin sobre capteniment de la via pública»","Art. 28 Ordenança d''ús de les vies: «Que les actuacions es facin en l''horari comprès entre les 10 i les 22 hores i no tinguin una durada superior als 30 minuts.»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, (select id from public.sources where url = 'https://ajuntament.barcelona.cat/norma-portal-juridic/ca/vid/840952155'), 'https://ajuntament.barcelona.cat/norma-portal-juridic/ca/vid/840952155', null, null, null, null
  from public.topics t where t.slug = 'gub-t15-ordenanca-us-vies'
on conflict (topic_id, locale) do update
   set outline = excluded.outline, key_ideas = excluded.key_ideas, glossary = excluded.glossary,
       amendments = excluded.amendments, source_id = excluded.source_id, source_url = excluded.source_url,
       page_from = excluded.page_from, page_to = excluded.page_to, key_ideas_page = excluded.key_ideas_page
 where (n.outline, n.key_ideas, n.glossary, n.amendments)
       is distinct from (excluded.outline, excluded.key_ideas, excluded.glossary, excluded.amendments);
insert into public.sources (title, url, kind, publisher, published_on) values ('Ordenança de circulació de vianants i de vehicles de Barcelona (text consolidat vigent, Norma. Portal Jurídic de Barcelona). Extracte literal', 'https://ajuntament.barcelona.cat/norma-portal-juridic/ca/vid/840951923', 'web_oficial'::public.source_kind, 'Ajuntament de Barcelona · Norma. Portal Jurídic de Barcelona', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('gub-t16-ordenanca-circulacio', 'Tema 16. Ordenança de circulació de vianants i de vehicles') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('guardia-urbana-barcelona') and t.slug = 'gub-t16-ordenanca-circulacio' on conflict do nothing;
insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'ca', '[{"n":"1","title":"Prioritat de pas i velocitats al nucli urbà"},{"n":"2","title":"Circulació de vehicles de motor, cicles i bicicletes"},{"n":"3","title":"Grups turístics i transport de mercaderies en bicicleta"},{"n":"4","title":"Vehicles de mobilitat personal (VMP)"},{"n":"5","title":"Retirada de vehicles i concurrència d''infraccions"}]'::jsonb, '["Art. 10 Ordenança de circulació: «Els i les vianants tenen prioritat sobre tot tipus de vehicles tal com queda regulat a la llei de trànsit i els seus reglaments de desenvolupament.»","Art. 11 Ordenança de circulació: «En els carrers on es circuli només per un carril, per sentit, i sense comptabilitzar els carrils reservats, els vehicles no poden circular a més de 30 km/h.»","Art. 13 Ordenança de circulació: «Els vehicles de motor i ciclomotors no poden circular per voreres, andanes, passeigs i carril-bici.»","VMP Ordenança de circulació: «L''edat mínima permesa per circular amb un vehicle de mobilitat personal és de 16 anys.»","VMP Ordenança de circulació: «Els vehicles de mobilitat personal per a transport personal o de mercaderies són vehicles d''una única plaça i no poden anar ocupats per més d''una persona.»","Art. 11 Ordenança de circulació: «En cas de pluja, d''obres, paviment deficient cal adaptar la velocitat com a mesura de precaució.»","Art. 11 Ordenança de circulació: «En els carrers que disposin de plataforma única de calçada i vorera, els vehicles no poden circular a més de 20 km/h, excepte senyalització específica.»","Art. 11 Ordenança de circulació: «En els carrers sense un espai destinat exclusivament al trànsit de vianants la velocitat màxima s''estableix en 10 km/h»","Art. 11 Ordenança de circulació: «a aquests efectes els carrils reservats per a la circulació de determinats usuaris o ús exclusiu de transport públic no es comptabilitzen»","Art. 10 Ordenança de circulació: «gaudeixen de prioritat sobre la resta de vehicles, però no sobre els i les vianants»","Art. 14 Ordenança de circulació: «ha de desenvolupar-se preferentment pel carril més proper a la vorera»","Art. 14 Ordenança de circulació: «Han d''evitar circular a menys d''1 metre de les façanes»","Art. 14 Ordenança de circulació: «quan el conductor sigui major d''edat, podrà transportar un menor, amb casc homologat, en seient addicional que haurà d''ésser igualment homologat»","VMP Ordenança de circulació: «Les persones conductores d''un vehicle de mobilitat personal estan obligades a fer servir un casc de protecció que compleixi alguna certificació apta per a bicicleta, skate o ciclomotor, o casc homologat per a motocicletes.»","VMP Ordenança de circulació: «En cap cas les persones conductores menors d''edat poden circular per les vies urbanes amb una taxa d''alcohol en sang superior a 0 grams per litre»","Concurrència Ordenança de circulació: «Cada dia que un vehicle romangui estacionat en lloc prohibit causa una infracció independent.»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, (select id from public.sources where url = 'https://ajuntament.barcelona.cat/norma-portal-juridic/ca/vid/840951923'), 'https://ajuntament.barcelona.cat/norma-portal-juridic/ca/vid/840951923', null, null, null, null
  from public.topics t where t.slug = 'gub-t16-ordenanca-circulacio'
on conflict (topic_id, locale) do update
   set outline = excluded.outline, key_ideas = excluded.key_ideas, glossary = excluded.glossary,
       amendments = excluded.amendments, source_id = excluded.source_id, source_url = excluded.source_url,
       page_from = excluded.page_from, page_to = excluded.page_to, key_ideas_page = excluded.key_ideas_page
 where (n.outline, n.key_ideas, n.glossary, n.amendments)
       is distinct from (excluded.outline, excluded.key_ideas, excluded.glossary, excluded.amendments);
insert into public.sources (title, url, kind, publisher, published_on) values ('Ordenança municipal de les activitats i dels establiments de concurrència pública de Barcelona (text vigent, Norma. Portal Jurídic de Barcelona). Extracte literal', 'https://ajuntament.barcelona.cat/norma-portal-juridic/ca/vid/840952006', 'web_oficial'::public.source_kind, 'Ajuntament de Barcelona · Norma. Portal Jurídic de Barcelona', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('gub-t17-ordenanca-concurrencia-publica', 'Tema 17. Ordenança de les activitats i dels establiments de concurrència pública') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('guardia-urbana-barcelona') and t.slug = 'gub-t17-ordenanca-concurrencia-publica' on conflict do nothing;
insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'ca', '[{"n":"1","title":"Objecte i classificació dels establiments de concurrència pública"},{"n":"2","title":"Llicència, contigüitat, distàncies i usos protegits"},{"n":"3","title":"Horaris, aforaments i conductes a l''exterior"},{"n":"4","title":"Dret d''admissió i condicions d''accés"},{"n":"5","title":"Infraccions, sancions, tancaments i prescripció"}]'::jsonb, '["Art. 5 Ordenança d''establiments de concurrència pública: «les activitats i els establiments de concurrència pública resten subjectes al previ atorgament per l''Ajuntament de la corresponent llicència municipal»","Art. 4 Ordenança d''establiments de concurrència pública: «Tenen la consideració d''espectacles o activitats recreatives de caràcter extraordinari les que es duen a terme de forma esporàdica o puntual.»","Art. 28 Ordenança d''establiments de concurrència pública: «Tots els establiments de concurrència pública han de disposar, a l''entrada del local i en lloc visible, d''un rètol o cartell informatiu amb l''aforament màxim autoritzat.»","Art. 67 Ordenança d''establiments de concurrència pública: «Les infraccions administratives en matèria de policia d''espectacles i d''activitats recreatives es poden qualificar de molt greus, faltes greus i faltes lleus.»","Art. 3 Ordenança d''establiments de concurrència pública: «Tipus III: estructures desmuntables, amb caràcter itinerant o sense.»","Art. 29 Ordenança d''establiments de concurrència pública: «els responsables dels establiments han d''impedir que el públic i demés usuaris surtin de l''establiment amb begudes»","Art. 27 Ordenança d''establiments de concurrència pública: «ha de quedar buit de públic en el termini màxim de vint-i-cinc minuts»","Art. 28 Ordenança d''establiments de concurrència pública: «Els establiments en els que s''exerceixin activitats musicals (2.2) i que disposin d''un aforament autoritzat superior a les 150 persones, han de disposar d''un comptador de persones»","Art. 26 Ordenança d''establiments de concurrència pública: «Les seus del Parlament de Catalunya, del Govern de la Generalitat, de l''Ajuntament i dels seus Consells de Districte»","Art. 25 Ordenança d''establiments de concurrència pública: «mesurant la línia recta imaginària que va des de les portes d''accés principal d''un i altre establiment, sense tenir en compte l''alçada de les edificacions»","Art. 25 Ordenança d''establiments de concurrència pública: «s''entén que hi ha contigüitat d''un establiment de concurrència pública amb un habitatge quan l''establiment limita amb l''habitatge per parets laterals, pel sostre o pel paviment»","Art. 68 Ordenança d''establiments de concurrència pública: «La negativa a permetre l''accés a agents de l''autoritat en exercici de les seves funcions, i facilitar l''acció inspectora.»","Art. 69 Ordenança d''establiments de concurrència pública: «L''excés de l''aforament permès sempre que no comporti un risc per a la seguretat de les persones.»","Art. 78 Ordenança d''establiments de concurrència pública: «les infraccions lleus prescriuen als sis mesos d''haver-se comès, les greus al cap d''un any i les molt greus al cap de dos anys»","Art. 56 Ordenança d''establiments de concurrència pública: «poden formular denúncia davant de l''Alcalde, de l''Administració de la Generalitat, dels agents de la Guàrdia Urbana i dels altres Cossos i Forces de Seguretat, de la Fiscalia o del Jutjat de Guàrdia»","Art. 53 Ordenança d''establiments de concurrència pública: «amb un format mínim de 30 cm d''amplada per 20 cm d''alçada, i les lletres de la inscripció han de ser en caixa alta, de 36 punts»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, (select id from public.sources where url = 'https://ajuntament.barcelona.cat/norma-portal-juridic/ca/vid/840952006'), 'https://ajuntament.barcelona.cat/norma-portal-juridic/ca/vid/840952006', null, null, null, null
  from public.topics t where t.slug = 'gub-t17-ordenanca-concurrencia-publica'
