insert into public.sources (title, url, kind, publisher, published_on) values ('Ordenança de protecció, tinença i venda d''animals de Barcelona (text consolidat vigent, Norma. Portal Jurídic de Barcelona). Extracte literal', 'https://ajuntament.barcelona.cat/norma-portal-juridic/ca/vid/840952021', 'web_oficial'::public.source_kind, 'Ajuntament de Barcelona · Norma. Portal Jurídic de Barcelona', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('gub-t18-ordenanca-animals', 'Tema 18. Ordenança de protecció, tinença i venda d''animals') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('guardia-urbana-barcelona') and t.slug = 'gub-t18-ordenanca-animals' on conflict do nothing;
insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'ca', '[{"n":"1","title":"Activitats prohibides i prohibició de regalar animals"},{"n":"2","title":"Infraccions molt greus, greus i lleus"},{"n":"3","title":"Sancions i inhabilitacions"},{"n":"4","title":"Gossos potencialment perillosos"},{"n":"5","title":"Control dels animals salvatges en captivitat"}]'::jsonb, '["Art. 40 Ordenança d''animals: «Els animals no poden ser objecte de regal o sorteig, rifa o promoció, ni poden ser lliurats com a cap tipus de premi, obsequi o recompensa.»","Art. 13 Ordenança d''animals: «Es prohibeix la tinença de cavalls i altres animals de tracció en patis d''habitatges o solars urbans.»","Art. 51 Ordenança d''animals: «Organitzar baralles d''animals i participar-hi.»","Art. 52 Ordenança d''animals: «Les infraccions lleus, des de 100 EUR fins a 400 EUR.»","Art. 53 Ordenança d''animals: «Tenir gossos potencialment perillosos sense disposar de la llicència.»","Art. 51 Ordenança d''animals: «No vacunar o no fer els tractaments obligatoris als animals de companyia.»","Art. 51 Ordenança d''animals: «Abandonar animals si no els pot comportar cap risc.»","Art. 51 Ordenança d''animals: «Exhibir animals als aparadors dels establiments de venda d''animals.»","Art. 51 Ordenança d''animals: «Mantenir els animals lligats més de dues hores i, en el cas dels cadells, durant més d''una hora»","Art. 51 Ordenança d''animals: «Vendre animals als menors de 16 anys i a incapacitats sense l''autorització dels qui en tenen la pàtria potestat o la custòdia.»","Art. 51 Ordenança d''animals: «Portar els animals a la via i als espais públics sense una placa identificativa o qualsevol altre mitjà adaptat al collar de l''animal en què consti el nom de l''animal i les dades de la persona propietària o posseïdora.»","Art. 52 Ordenança d''animals: «comporta la imposició de la sanció establerta en el seu grau màxim de 300 a 400 EUR»","Art. 53 Ordenança d''animals: «Tenir un gos potencialment perillós en llocs públics sense morrió o sense estar subjecte amb una cadena.»","Art. 53 Ordenança d''animals: «Tenir més d''un gos potencialment perillós per persona a les vies i als espais públics.»","Art. 13 Ordenança d''animals: «es prohibeix el manteniment de bovins i d''altra classe de bestiar destinat a la producció làctia (vaqueries) i d''animals per al consum»","Art. 53 Ordenança d''animals: «Abandonar un gos potencialment perillós, la qual cosa succeeix quan l''animal no va acompanyat de cap persona amb independència que dugui la identificació o no.»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, (select id from public.sources where url = 'https://ajuntament.barcelona.cat/norma-portal-juridic/ca/vid/840952021'), 'https://ajuntament.barcelona.cat/norma-portal-juridic/ca/vid/840952021', null, null, null, null
  from public.topics t where t.slug = 'gub-t18-ordenanca-animals'
on conflict (topic_id, locale) do update
   set outline = excluded.outline, key_ideas = excluded.key_ideas, glossary = excluded.glossary,
       amendments = excluded.amendments, source_id = excluded.source_id, source_url = excluded.source_url,
