insert into public.sources (title, url, kind, publisher, published_on) values ('Ordenança per la qual es fixen els criteris d''accés, circulació i estacionament de vehicles en la Zona de Baixes Emissions de Barcelona i es promou una mobilitat sense emissions (text vigent, Norma. Portal Jurídic de Barcelona). Extracte literal', 'https://ajuntament.barcelona.cat/norma-portal-juridic/ca/vid/923546402', 'web_oficial'::public.source_kind, 'Ajuntament de Barcelona · Norma. Portal Jurídic de Barcelona', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('gub-t19-ordenanca-zbe', 'Tema 19. Ordenança de la Zona de Baixes Emissions de Barcelona') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('guardia-urbana-barcelona') and t.slug = 'gub-t19-ordenanca-zbe' on conflict do nothing;
insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'ca', '[{"n":"1","title":"Objecte, finalitat i àmbit de la Zona de Baixes Emissions"},{"n":"2","title":"Restricció d''accés i horari"},{"n":"3","title":"Excepcions, exempcions i autoritzacions"},{"n":"4","title":"Control, senyalització i seguiment"},{"n":"5","title":"Procediment sancionador i sancions"}]'::jsonb, '["Art. 10 Ordenança ZBE: «La mesura establerta a l’apartat 1 és d’aplicació de dilluns a divendres feiners, en horari de 07:00 hores a 20:00 hores.»","Art. 20 Ordenança ZBE: «constitueix una infracció greu, sancionable amb multa de 200 euros, incomplir la prohibició establerta a l’article 10»","Art. 4 Ordenança ZBE: «Aquesta Ordenança s’aplica al terme municipal de Barcelona i als vehicles que hi accedeixin, hi circulin o hi estacionin.»","Art. 3 Ordenança ZBE: «La responsabilitat d’assolir els objectius establerts a l’article 2 correspon tant a l’Ajuntament de Barcelona com a la ciutadania en el seu conjunt.»","Art. 16 Ordenança ZBE: «El control del compliment de les disposicions d’aquesta Ordenança es realitza mitjançant un sistema de lectura de matrícules i la plataforma tecnològica de l’Ajuntament amb mitjans automàtics»","Art. 17 Ordenança ZBE: «mitjançant la senyalització aprovada a l’efecte per la Direcció General de Trànsit»","Art. 20 Ordenança ZBE: «l’import de la multa és de 260 euros»","Art. 19 Ordenança ZBE: «El procediment sancionador d’aquesta Ordenança és l’establert al Text refós de la Llei sobre trànsit, circulació de vehicles de motor i seguretat vial»","Art. 14 Ordenança ZBE: «Vehicles de serveis d’emergència i essencials.»","Art. 12 Ordenança ZBE: «Amb caràcter excepcional, per raons d’interès general, pot autoritzar-se l’accés a la ZBE, mitjançant resolució motivada de l’alcalde o alcaldessa.»","Art. 13 Ordenança ZBE: «L’Àrea Metropolitana de Barcelona gestiona el Registre metropolità de vehicles estrangers i altres vehicles autoritzats a les zones de baixes emissions»","Art. 15 Ordenança ZBE: «com a màxim 24 hores després del moment que efectivament hagi accedit a la ZBE»","Art. 12 Ordenança ZBE: «comporta l’activació simultània per part de l’òrgan municipal competent del Protocol d’actuació davant d’episodis d’alta contaminació atmosfèrica previst en el Pla bàsic d’emergències municipal»","Art. 11 Ordenança ZBE: «s’estableixen a través de l’Ordenança fiscal relativa a les taxes per estacionament regulat de vehicles a la via pública (AREA)»","Art. 9 Ordenança ZBE: «s’aplica l’Ordenança de circulació de vianants i de vehicles, de 27 de novembre de 1998»","Art. 15 Ordenança ZBE: «en el qual cas es pot tramitar en el termini de tres dies, comptats a partir del mateix dia en què hagi tingut lloc»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, (select id from public.sources where url = 'https://ajuntament.barcelona.cat/norma-portal-juridic/ca/vid/923546402'), 'https://ajuntament.barcelona.cat/norma-portal-juridic/ca/vid/923546402', null, null, null, null
  from public.topics t where t.slug = 'gub-t19-ordenanca-zbe'
on conflict (topic_id, locale) do update
   set outline = excluded.outline, key_ideas = excluded.key_ideas, glossary = excluded.glossary,
