insert into public.sources (title, url, kind, publisher, published_on) values ('Ley 16/1991, de 10 de julio, de las Policías Locales (Cataluña) (texto consolidado, BOE)', 'https://www.boe.es/buscar/act.php?id=BOE-A-1991-20343', 'boe'::public.source_kind, 'Agencia Estatal Boletín Oficial del Estado', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('gub-t21-policies-locals', 'Tema 21. Llei 16/1991, de les policies locals de Catalunya') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('guardia-urbana-barcelona') and t.slug = 'gub-t21-policies-locals' on conflict do nothing;
insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'ca', '[{"n":"1","title":"Àmbit i naturalesa de les policies locals de Catalunya"},{"n":"2","title":"Creació, àmbit territorial i armament"},{"n":"3","title":"Funcions de les policies locals i dels vigilants"},{"n":"4","title":"Coordinació de les policies locals"},{"n":"5","title":"Escales, categories i comandament"},{"n":"6","title":"Règim estatutari i accés"}]'::jsonb, '["Art. 2 Llei 16/1991: «pueden recibir también la denominación específica de Policía municipal o de Guardia urbana»","Art. 2 Llei 16/1991: «Las Policías locales son institutos armados de naturaleza civil con estructura y organización jerarquizadas.»","Art. 3 Llei 16/1991: «Puede existir Policía local en los Municipios de más de 10.000 habitantes.»","Art. 5 Llei 16/1991: «El ámbito de actuación de las Policías locales viene constituido por el territorio del correspondiente Municipio.»","Art. 24 Llei 16/1991: «d) Escala básica, que comprende las categorías de Cabo y de Agente.»","Art. 28 Llei 16/1991: «Los Policías locales son funcionarios de carrera de los Ayuntamientos respectivos»","Art. 24 Llei 16/1991: «b) Escala ejecutiva, que comprende la categoría de Inspector.»","Art. 24 Llei 16/1991: «d) A la escala básica, el grupo C, subgrupo C1.»","Art. 1 Llei 16/1991: «será prestado directamente por las respectivas Corporaciones locales, que no pueden constituir órganos especiales de gestión ni aprobar la concesión, el arrendamiento ni ninguna otra forma de gestión indirecta del servicio»","Art. 8 Llei 16/1991: «El Alcalde determinará, de forma motivada, las circunstancias y los servicios en que no se llevarán armas de fuego.»","Art. 8 Llei 16/1991: «Los vigilantes a que se refiere el artículo 1.2 no pueden llevar armas de fuego.»","Art. 26 Llei 16/1991: «Es jefe del cuerpo el miembro de la plantilla de mayor graduación»","Art. 13 Llei 16/1991: «Los Vigilantes a que se refiere el artículo 1.2 pueden realizar únicamente las actuaciones siguientes:»","Art. 6 Llei 16/1991: «jurarán o prometerán acatar la Constitución, como norma fundamental del Estado, y respetar y observar el Estatuto de Autonomía»","Art. 41 Llei 16/1991: «Las Corporaciones Locales garantizarán la necesaria defensa jurídica a sus Policías locales»","Art. 3 Llei 16/1991: «si acuerda su creación la mayoría absoluta del número legal de miembros de la correspondiente Corporación local y lo autoriza el Consejero de Gobernación, previo informe de la Comisión de Coordinación de las Policías Locales»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1991-20343'), 'https://www.boe.es/buscar/act.php?id=BOE-A-1991-20343', null, null, null, null
