insert into public.sources (title, url, kind, publisher, published_on) values ('Ley 4/2003, de 7 de abril, de ordenación del sistema de seguridad pública de Cataluña (texto consolidado, BOE)', 'https://www.boe.es/buscar/act.php?id=BOE-A-2003-9620', 'boe'::public.source_kind, 'Agencia Estatal Boletín Oficial del Estado', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('gub-t22-sistema-seguretat-publica', 'Tema 22. Llei 4/2003, d''ordenació del sistema de seguretat pública de Catalunya') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('guardia-urbana-barcelona') and t.slug = 'gub-t22-sistema-seguretat-publica' on conflict do nothing;
insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'ca', '[{"n":"1","title":"Objecte i principis del sistema de seguretat pública de Catalunya"},{"n":"2","title":"Autoritats i cossos policials"},{"n":"3","title":"Òrgans de coordinació i participació"},{"n":"4","title":"Juntes locals de seguretat i mesa de coordinació operativa"},{"n":"5","title":"Planificació i drets dels ciutadans"}]'::jsonb, '["Art. 3 Llei 4/2003: «La Junta de Seguridad de Cataluña es el órgano superior de coordinación entre la Policía de la Generalidad y las fuerzas y cuerpos de seguridad del Estado»","Art. 5 Llei 4/2003: «La Policía de la Generalidad-Mossos d''Esquadra y las policías de los ayuntamientos, con la denominación de policía local, policía municipal, guardia urbana o cualquier otra denominación tradicional, constituyen la policía de las instituciones propias de Cataluña.»","Art. 9 Llei 4/2003: «La junta local de seguridad está integrada por el alcalde o la alcalde, que la preside, con voz y voto»","Art. 4 Llei 4/2003: «En el ámbito local, los alcaldes son también autoridades superiores en materia de seguridad, en el marco de sus competencias.»","Art. 6 Llei 4/2003: «El Consejo de Seguridad de Cataluña es el órgano consultivo y de participación superior en Cataluña en materia de seguridad»","Art. 9 Llei 4/2003: «En los municipios que tengan policía local debe existir una junta local de seguridad»","Art. 2 Llei 4/2003: «c) Proximidad a los ciudadanos y descentralización de los servicios públicos.»","Art. 3 Llei 4/2003: «b) Los cuerpos policiales y demás servicios, públicos o privados, de seguridad.»","Art. 5 Llei 4/2003: «La policía local de cada municipio debe integrarse en un solo cuerpo y su ámbito de actuación es el del término municipal correspondiente.»","Art. 8 Llei 4/2003: «b) Cinco vocales en representación de los ayuntamientos.»","Art. 11 Llei 4/2003: «Las juntas locales de seguridad deben crear una mesa de coordinación operativa, como órgano permanente y estable de coordinación y cooperación de los diversos cuerpos y servicios de seguridad en el municipio.»","Art. 10 Llei 4/2003: «b) Elaborar y aprobar el plan de seguridad local y los planes de actuación específicos que sean procedentes en el ámbito respectivo»","Art. 14 Llei 4/2003: «La Escuela de Policía de Cataluña es un organismo autónomo de carácter administrativo adscrito al departamento titular de las competencias en materia de seguridad pública»","Art. 15 Llei 4/2003: «El Plan de seguridad de Cataluña tiene periodicidad cuatrienal»","Art. 34 Llei 4/2003: «Los ciudadanos pueden dirigir a las autoridades de seguridad las quejas y peticiones que crean oportunas sobre la prestación de los diversos servicios de seguridad y la actuación de los agentes.»","Art. 9 Llei 4/2003: «b) El concejal o concejala delegado en materia de seguridad ciudadana.»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2003-9620'), 'https://www.boe.es/buscar/act.php?id=BOE-A-2003-9620', null, null, null, null
