insert into public.sources (title, url, kind, publisher, published_on) values ('Ley Orgánica 4/2015, de 30 de marzo, de protección de la seguridad ciudadana (texto consolidado, BOE)', 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-3442', 'boe'::public.source_kind, 'Agencia Estatal Boletín Oficial del Estado', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('gub-t23-seguretat-ciutadana', 'Tema 23. Llei orgànica 4/2015, de protecció de la seguretat ciutadana') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('guardia-urbana-barcelona') and t.slug = 'gub-t23-seguretat-ciutadana' on conflict do nothing;
insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'ca', '[{"n":"1","title":"Objecte de la Llei de protecció de la seguretat ciutadana"},{"n":"2","title":"Documentació: DNI i passaport"},{"n":"3","title":"Identificació de persones i llibre registre"},{"n":"4","title":"Controls, comprovacions i registres corporals"},{"n":"5","title":"Mesures de seguretat extraordinàries"}]'::jsonb, '["Art. 9 LO 4/2015: «El Documento Nacional de Identidad es obligatorio a partir de los catorce años.»","Art. 8 LO 4/2015: «Es el único documento con suficiente valor por sí solo para la acreditación, a todos los efectos, de la identidad y los datos personales de su titular.»","Art. 16 LO 4/2015: «por el tiempo estrictamente necesario, que en ningún caso podrá superar las seis horas»","Art. 20 LO 4/2015: «a) El registro se realizará por un agente del mismo sexo que la persona sobre la que se practique esta diligencia.»","Art. 1 LO 4/2015: «su salvaguarda, como bien jurídico de carácter colectivo, es función del Estado, con sujeción a la Constitución y a las Leyes»","Art. 19 LO 4/2015: «no estarán sujetas a las mismas formalidades que la detención»","Art. 16 LO 4/2015: «a) Cuando existan indicios de que han podido participar en la comisión de una infracción.»","Art. 16 LO 4/2015: «se les deberá expedir a su salida un volante acreditativo del tiempo de permanencia en ellas, la causa y la identidad de los agentes actuantes»","Art. 16 LO 4/2015: «Los asientos de este libro-registro se cancelarán de oficio a los tres años.»","Art. 16 LO 4/2015: «El órgano competente de la Administración remitirá mensualmente al Ministerio Fiscal extracto de las diligencias de identificación»","Art. 9 LO 4/2015: «De su sustracción o extravío deberá darse cuenta tan pronto como sea posible a la comisaría de Policía o puesto de las Fuerzas y Cuerpos de Seguridad más próximo.»","Art. 20 LO 4/2015: «se efectuará en un lugar reservado y fuera de la vista de terceros»","Art. 21 LO 4/2015: «Dichas medidas podrán adoptarse por los agentes de la autoridad si la urgencia de la situación lo hiciera imprescindible, incluso mediante órdenes verbales.»","Art. 19 LO 4/2015: «si éste se negara a firmarla, se dejará constancia expresa de su negativa»","Art. 18 LO 4/2015: «incluso de las armas que se porten con licencia, permiso o autorización si se estima necesario»","Art. 20 LO 4/2015: «adoptando las medidas de compulsión indispensables, conforme a los principios de idoneidad, necesidad y proporcionalidad»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-3442'), 'https://www.boe.es/buscar/act.php?id=BOE-A-2015-3442', null, null, null, null
