insert into public.sources (title, url, kind, publisher, published_on) values ('Acord GOV/25/2015, de 24 de febrer, pel qual s''aprova el Codi d''ètica de la Policia de Catalunya (DOGC; text del Portal Jurídic de Catalunya). Extracte literal', 'https://portaljuridic.gencat.cat/ca/document-del-pjur/?documentId=685656', 'web_oficial'::public.source_kind, 'Generalitat de Catalunya · Portal Jurídic de Catalunya', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('gub-t24-codi-etica', 'Tema 24. El Codi d''ètica de la Policia de Catalunya (Acord GOV/25/2015)') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('guardia-urbana-barcelona') and t.slug = 'gub-t24-codi-etica' on conflict do nothing;
insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'ca', '[{"n":"1","title":"Finalitat del Codi d''ètica de la Policia de Catalunya"},{"n":"2","title":"Principis ètics"},{"n":"3","title":"Valors i competències per àrees"},{"n":"4","title":"La professió al servei de les persones"},{"n":"5","title":"Funcions, drets i deures dels agents"}]'::jsonb, '["Annex I Codi d''ètica de la Policia de Catalunya: «S’entén per principis aquelles bases que en cap cas un policia no pot deixar de respectar en la seva actuació. Es concreten en tres»","Annex I Codi d''ètica de la Policia de Catalunya: «Els valors, les actituds i les competències s’agrupen en cinc àrees: la funció pública, la professió, l’orientació a les persones, les relacions institucionals i l’entorn.»","Annex I.B Codi d''ètica de la Policia de Catalunya: «Per proximitat s’entén que l’agent de policia ha de ser accessible al ciutadà i ha d’exercir la funció que li correspon amb amabilitat i empatia»","Annex I.B Codi d''ètica de la Policia de Catalunya: «El seny és aquella qualitat humana que mou a la pràctica del discerniment abans d’emprendre les decisions.»","Annex II.7 Codi d''ètica de la Policia de Catalunya: «no poden acceptar ni oferir tracte de favor, contraprestacions ni regals per haver desenvolupat o per desenvolupar el servei públic que els correspon»","Acord GOV/25/2015 Codi d''ètica de la Policia de Catalunya: «a proposta del conseller d’Interior, el Govern»","Annex I.B Codi d''ètica de la Policia de Catalunya: «Exigeix una doble competència: una de tipus tècnic, que es refereix als coneixements, a les destreses i a les pràctiques pròpies de la professió, i una altra de tipus ètic»","Annex I.B Codi d''ètica de la Policia de Catalunya: «La temprança és aquella qualitat humana que predisposa a l''autodomini mental, al control emocional i a l’autoconsciència»","Annex I.C Codi d''ètica de la Policia de Catalunya: «també s’hi ha d’incloure l’obligació de denunciar i de perseguir tot acte de corrupció o qualsevol proposta que signifiqui un afavoriment indegut, injustificat o il·legal»","Annex I.A Codi d''ètica de la Policia de Catalunya: «La Policia de Catalunya té com a fita l’interès general, entès com el bé consensuat i no pas com la suma dels interessos particulars.»","Annex I.D Codi d''ètica de la Policia de Catalunya: «El sentiment de pertinença s’expressa a través del valor de la lleialtat i el compromís amb la institució.»","Annex I.D Codi d''ètica de la Policia de Catalunya: «No ha de ser, en cap cas, un pretext per ocultar mancances, limitacions o males pràctiques.»","Annex II.8 Codi d''ètica de la Policia de Catalunya: «els agents de policia s’han d’abstenir d’expressar públicament les seves legítimes opcions polítiques o religioses»","Annex II.5 Codi d''ètica de la Policia de Catalunya: «Si l’agent de policia considera que no està en condicions de desenvolupar correctament la funció que li correspon dins del cos policial, ho ha de comunicar al seu superior.»","Annex I Codi d''ètica de la Policia de Catalunya: «a. Garantir els drets i les llibertats de totes les persones, b. Actuar amb integritat, proporcionalitat, congruència i oportunitat, i c. Actuar amb absoluta neutralitat política i imparcialitat.»","Annex II.11 Codi d''ètica de la Policia de Catalunya: «S''entén per grup vulnerable aquell conjunt de persones que, per les seves característiques o circumstàncies, pateixen una situació de fragilitat que exigeix cura i protecció.»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, (select id from public.sources where url = 'https://portaljuridic.gencat.cat/ca/document-del-pjur/?documentId=685656'), 'https://portaljuridic.gencat.cat/ca/document-del-pjur/?documentId=685656', null, null, null, null
  from public.topics t where t.slug = 'gub-t24-codi-etica'
