insert into public.sources (title, url, kind, publisher, published_on) values ('Ley Orgánica 7/2021, de 26 de mayo, de protección de datos personales tratados para fines de prevención, detección, investigación y enjuiciamiento de infracciones penales y de ejecución de sanciones penales (texto consolidado, BOE)', 'https://www.boe.es/buscar/act.php?id=BOE-A-2021-8806', 'boe'::public.source_kind, 'Agencia Estatal Boletín Oficial del Estado', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('gub-t26-dades-fins-penals', 'Tema 26. Llei orgànica 7/2021, de protecció de dades amb fins penals') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('guardia-urbana-barcelona') and t.slug = 'gub-t26-dades-fins-penals' on conflict do nothing;
insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'ca', '[{"n":"1","title":"Objecte i autoritats competents (LO 7/2021)"},{"n":"2","title":"Principis del tractament i terminis de conservació"},{"n":"3","title":"Categories d''interessats i dades especials"},{"n":"4","title":"Sistemes de gravació d''imatges i so de les FCS"},{"n":"5","title":"Delegat de protecció de dades i règim sancionador"}]'::jsonb, '["Art. 18 LO 7/2021: «Las grabaciones serán destruidas en el plazo máximo de tres meses desde su captación»","Art. 4 LO 7/2021: «a) Las Fuerzas y Cuerpos de Seguridad.»","Art. 40 LO 7/2021: «Los responsables del tratamiento designarán, en todo caso, un delegado de protección de datos.»","Art. 6 LO 7/2021: «c) Adecuados, pertinentes y no excesivos en relación con los fines para los que son tratados.»","Art. 1 LO 7/2021: «con fines de prevención, detección, investigación y enjuiciamiento de infracciones penales o de ejecución de sanciones penales»","Art. 4 LO 7/2021: «También tendrán consideración de autoridades competentes las Autoridades judiciales del orden jurisdiccional penal y el Ministerio Fiscal.»","Art. 8 LO 7/2021: «Con carácter general, el plazo máximo para la supresión de los datos será de veinte años»","Art. 18 LO 7/2021: «en todo caso, en el plazo máximo de setenta y dos horas desde su grabación»","Art. 17 LO 7/2021: «por un periodo máximo de un mes prorrogable por otro»","Art. 17 LO 7/2021: «siendo comunicada tal actuación con la mayor brevedad posible, y siempre en el plazo de 24 horas»","Art. 16 LO 7/2021: «Se entenderá por videocámara fija aquella anclada a un soporte fijo o fachada, aunque el sistema de grabación se pueda mover en cualquier dirección.»","Art. 17 LO 7/2021: «La toma de imagen y sonido, que ha de ser conjunta, queda supeditada, en todo caso, a la concurrencia de un peligro o evento concreto.»","Art. 9 LO 7/2021: «b) Personas condenadas o sancionadas por una infracción penal.»","Art. 18 LO 7/2021: «se remitirán al órgano competente, de inmediato, para el inicio del oportuno procedimiento sancionador»","Art. 63 LO 7/2021: «prescribirán a los seis meses, a los dos o a los tres años de haberse cometido, según sean leves, graves o muy graves, respectivamente»","Art. 18 LO 7/2021: «De no poder redactarse el atestado en tal plazo, se relatarán verbalmente los hechos a la autoridad judicial, o al Ministerio Fiscal, junto con la entrega de la grabación.»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2021-8806'), 'https://www.boe.es/buscar/act.php?id=BOE-A-2021-8806', null, null, null, null
  from public.topics t where t.slug = 'gub-t26-dades-fins-penals'
