insert into public.sources (title, url, kind, publisher, published_on) values ('Ley 11/2009, de 6 de julio, de regulación administrativa de los espectáculos públicos y las actividades recreativas (Cataluña) (texto consolidado, BOE)', 'https://www.boe.es/buscar/act.php?id=BOE-A-2009-12856', 'boe'::public.source_kind, 'Agencia Estatal Boletín Oficial del Estado', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('gub-t27-espectacles-publics', 'Tema 27. Llei 11/2009, dels espectacles públics i les activitats recreatives') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('guardia-urbana-barcelona') and t.slug = 'gub-t27-espectacles-publics' on conflict do nothing;
insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'ca', '[{"n":"1","title":"Dret d''admissió i protecció de menors"},{"n":"2","title":"Control d''accés i inspeccions"},{"n":"3","title":"Faltes molt greus, greus i lleus"},{"n":"4","title":"Sancions"},{"n":"5","title":"Mesures provisionals immediates i prescripció"}]'::jsonb, '["Art. 57 Llei 11/2009: «Las faltas muy graves prescriben al cabo de tres años; las faltas graves, al cabo de dos años, y las faltas leves, al cabo de seis meses.»","Art. 10 Llei 11/2009: «El ejercicio del derecho de admisión no puede conllevar, en ningún caso, discriminación por razón de nacimiento, raza, sexo, religión, opinión, discapacidad, orientación sexual, identidad de género o cualquier otra condición o circunstancia personal o social»","Art. 47 Llei 11/2009: «f) No permitir el acceso a los agentes de la autoridad en el ejercicio de sus funciones»","Art. 47 Llei 11/2009: «c) Exceder el aforo permitido, si supone un riesgo para la seguridad de las personas.»","Art. 44 Llei 11/2009: «los cuales, en el ejercicio de sus funciones, tienen el carácter de agentes de la autoridad»","Art. 44 Llei 11/2009: «Como resultado de la inspección, los agentes actuantes deben extender un acta, en la cual los interesados pueden hacer constar su disconformidad y observaciones.»","Art. 65 Llei 11/2009: «los agentes de policía deben comunicarlo, dentro de las cuarenta y ocho horas siguientes, al órgano competente»","Art. 65 Llei 11/2009: «El incumplimiento de dichos plazos conlleva automáticamente el levantamiento de las medidas provisionales inmediatas adoptadas.»","Art. 48 Llei 11/2009: «i) Permitir el acceso a establecimientos abiertos al público, espectáculos públicos o actividades recreativas de personas que exhiban símbolos, indumentaria u objetos que inciten a la violencia, al racismo o a la xenofobia.»","Art. 47 Llei 11/2009: «Incumplir de forma grave y reiterada, como mínimo tres veces en un período de seis meses»","Art. 47 Llei 11/2009: «i) Incumplir la prohibición de discriminación establecida por el artículo 10.»","Art. 52 Llei 11/2009: «b) Si los infractores son espectadores o usuarios, una multa de 50 a 150 euros»","Art. 50 Llei 11/2009: «a) Una multa de 10.001 a 100.000 euros»","Art. 48 Llei 11/2009: «j) Incumplir los horarios de inicio o finalización de un espectáculo público o una actividad recreativa, o bien los horarios de apertura o cierre de los establecimientos abiertos al público.»","Art. 9 Llei 11/2009: «el órgano competente para autorizarlos puede prohibir la asistencia a los menores»","Art. 51 Llei 11/2009: «mediante el cierre y precinto, para ninguna actividad relacionada con los espectáculos públicos o actividades recreativas por un período máximo de seis meses»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2009-12856'), 'https://www.boe.es/buscar/act.php?id=BOE-A-2009-12856', null, null, null, null
  from public.topics t where t.slug = 'gub-t27-espectacles-publics'
on conflict (topic_id, locale) do update
   set outline = excluded.outline, key_ideas = excluded.key_ideas, glossary = excluded.glossary,
