insert into public.sources (title, url, kind, publisher, published_on) values ('Ley Orgánica 6/1984, de 24 de mayo, reguladora del procedimiento de «Habeas Corpus» (texto consolidado, BOE)', 'https://www.boe.es/buscar/act.php?id=BOE-A-1984-11620', 'boe'::public.source_kind, 'Agencia Estatal Boletín Oficial del Estado', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('gub-t29-habeas-corpus', 'Tema 29. Llei orgànica 6/1984, del procediment d''habeas corpus') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('guardia-urbana-barcelona') and t.slug = 'gub-t29-habeas-corpus' on conflict do nothing;
insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'ca', '[{"n":"1","title":"Concepte i supòsits de detenció il·legal"},{"n":"2","title":"Competència i legitimació"},{"n":"3","title":"Inici del procediment i deures de l''autoritat que custodia"},{"n":"4","title":"Tramitació: incoació, audiència i termini de 24 hores"},{"n":"5","title":"Resolució i costes"}]'::jsonb, '["Art. 1 LO 6/1984: «se podrá obtener la inmediata puesta a disposición de la Autoridad judicial competente, de cualquier persona detenida ilegalmente»","Art. 2 LO 6/1984: «Es competente para conocer la solicitud de «Habeas Corpus» el Juez de Instrucción del lugar en que se encuentre la persona privada de libertad»","Art. 4 LO 6/1984: «no siendo preceptiva la intervención de Abogado ni de Procurador»","Art. 5 LO 6/1984: «estarán obligados a poner inmediatamente en conocimiento del Juez competente la solicitud de «Habeas Corpus»»","Art. 7 LO 6/1984: «En el plazo de veinticuatro horas, contadas desde que sea dictado el auto de incoación»","Art. 1 LO 6/1984: «d) Las privadas de libertad a quienes no les sean respetados los derechos que la Constitución y las leyes procesales garantizan a toda persona detenida.»","Art. 1 LO 6/1984: «a) Las que lo fueren por una autoridad, agente de la misma, funcionario público o particular, sin que concurran los supuestos legales»","Art. 6 LO 6/1984: «Contra la resolución que en uno u otro caso se adopte, no cabrá recurso alguno.»","Art. 6 LO 6/1984: «dará traslado de la misma al Ministerio Fiscal»","Art. 2 LO 6/1984: «el procedimiento deberá seguirse ante el Juez Central de Instrucción correspondiente»","Art. 8 LO 6/1984: «acordará el archivo de las actuaciones, declarando ser conforme a Derecho la privación de libertad»","Art. 8 LO 6/1984: «en establecimiento distinto, o bajo la custodia de personas distintas a las que hasta entonces la detentaban»","Art. 5 LO 6/1984: «Si incumplieren esta obligación, serán apercibidos por el Juez, sin perjuicio de las responsabilidades penales y disciplinarias en que pudieran incurrir.»","Art. 3 LO 6/1984: «Asimismo, lo podrá iniciar, de oficio, el Juez competente a que se refiere el artículo anterior.»","Art. 2 LO 6/1984: «en defecto de los anteriores, el del lugar donde se hayan tenido las últimas noticias sobre el paradero del detenido»","Art. 9 LO 6/1984: «si se apreciase temeridad o mala fe, será condenado el solicitante al pago de las costas del procedimiento»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1984-11620'), 'https://www.boe.es/buscar/act.php?id=BOE-A-1984-11620', null, null, null, null
  from public.topics t where t.slug = 'gub-t29-habeas-corpus'
on conflict (topic_id, locale) do update
   set outline = excluded.outline, key_ideas = excluded.key_ideas, glossary = excluded.glossary,
