insert into public.topics (slug, title) values ('gub-t31-codi-penal', 'Tema 31. El Codi penal: lesions, llibertat, integritat moral, llibertat sexual, patrimoni i seguretat viària') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('guardia-urbana-barcelona') and t.slug = 'gub-t31-codi-penal' on conflict do nothing;
insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'ca', '[{"n":"1","title":"Lesions i maltractament"},{"n":"2","title":"Amenaces i coaccions"},{"n":"3","title":"Delictes contra la seguretat viària"},{"n":"4","title":"Maltractament animal i delictes d''odi"},{"n":"5","title":"Omissió del deure d''impedir delictes"},{"n":"6","title":"Atemptat, resistència i desobediència"}]'::jsonb, '["Art. 379 Codi penal: «con una tasa de alcohol en aire espirado superior a 0,60 miligramos por litro o con una tasa de alcohol en sangre superior a 1,2 gramos por litro»","Art. 383 Codi penal: «se negare a someterse a las pruebas legalmente establecidas para la comprobación de las tasas de alcoholemia y la presencia de las drogas tóxicas»","Art. 384 Codi penal: «al que condujere un vehículo de motor o ciclomotor sin haber obtenido nunca permiso o licencia de conducción»","Art. 550 Codi penal: «Son reos de atentado los que agredieren o, con intimidación grave o violencia, opusieren resistencia grave a la autoridad, a sus agentes o funcionarios públicos, o los acometieren»","Art. 147 Codi penal: «siempre que la lesión requiera objetivamente para su sanidad, además de una primera asistencia facultativa, tratamiento médico o quirúrgico»","Art. 556 Codi penal: «Los que faltaren al respeto y consideración debida a la autoridad, en el ejercicio de sus funciones, serán castigados con la pena de multa de uno a tres meses.»","Art. 379 Codi penal: «a velocidad superior en sesenta kilómetros por hora en vía urbana o en ochenta kilómetros por hora en vía interurbana a la permitida reglamentariamente»","Art. 147 Codi penal: «La simple vigilancia o seguimiento facultativo del curso de la lesión no se considerará tratamiento médico.»","Art. 147 Codi penal: «El que golpeare o maltratare de obra a otro sin causarle lesión, será castigado con la pena de multa de uno a dos meses.»","Art. 172 Codi penal: «Cuando la coacción ejercida tuviera como objeto impedir el ejercicio de un derecho fundamental se le impondrán las penas en su mitad superior»","Art. 380 Codi penal: «El que condujere un vehículo a motor o un ciclomotor con temeridad manifiesta y pusiere en concreto peligro la vida o la integridad de las personas»","Art. 385 Codi penal: «Colocando en la vía obstáculos imprevisibles, derramando sustancias deslizantes o inflamables o mutando, sustrayendo o anulando la señalización o por cualquier otro medio.»","Art. 551 Codi penal: «3.º Acometiendo a la autoridad, a su agente o al funcionario público haciendo uso de un vehículo de motor.»","Art. 450 Codi penal: «El que, pudiendo hacerlo con su intervención inmediata y sin riesgo propio o ajeno, no impidiere la comisión de un delito que afecte a las personas en su vida, integridad o salud, libertad o libertad sexual»","Art. 556 Codi penal: «o al personal de seguridad privada, debidamente identificado, que desarrolle actividades de seguridad privada en cooperación y bajo el mando de las Fuerzas y Cuerpos de Seguridad»","Art. 340 bis Codi penal: «Será castigado con la pena de prisión de tres a dieciocho meses o multa de seis a doce meses y con la pena de inhabilitación especial de uno a tres años»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444'), 'https://www.boe.es/buscar/act.php?id=BOE-A-1995-25444', null, null, null, null
  from public.topics t where t.slug = 'gub-t31-codi-penal'
on conflict (topic_id, locale) do update
   set outline = excluded.outline, key_ideas = excluded.key_ideas, glossary = excluded.glossary,
