insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('guardia-urbana-barcelona') and t.slug = 'gub-t32-armes' on conflict do nothing;
insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'ca', '[{"n":"1","title":"Reglament d''armes: categories i armes prohibides"},{"n":"2","title":"Llicències i prohibicions de port"},{"n":"3","title":"Armament reglamentari de les policies locals"},{"n":"4","title":"Custòdia: armers, revistes i pèrdues"},{"n":"5","title":"Retirada de l''arma i guia de pertinença"},{"n":"6","title":"Control psicotècnic, mèdic i formació en tir"}]'::jsonb, '["Art. 3 RD 137/1993: «Armas de fuego cortas: Comprende las pistolas y revólveres.»","Art. 96 RD 137/1993: «La tenencia y el uso de las armas de las categorías 1.ª, 2.ª y 3.ª precisará de licencia de armas.»","Art. 2 D219 Decret 219/1996: «Tant les armes de foc com la seva munició són propietat dels ajuntaments respectius.»","Art. 4 D219 Decret 219/1996: «L''arma de foc es durà sempre que s''estigui de servei.»","Art. 8 D219 Decret 219/1996: «8.1 Els membres de la policia local estaran dotats d''un revòlver de calibre 0.38 SPL amb una longitud de canó entre 3'' i 4''.»","Art. 19 D219 Decret 219/1996: «on cada agent, en acabar el servei, dipositarà l''arma reglamentària, llevat d''autorització expressa en contrari de l''alcalde o persona en qui delegui»","Art. 114 RD 137/1993: «d) Los miembros de los Cuerpos de Policía de las Comunidades Autónomas y de las Corporaciones locales.»","Art. 4 RD 137/1993: «Se considerarán puñales a estos efectos las armas blancas de hoja menor de 11 centímetros, de dos filos y puntiaguda.»","Art. 147 RD 137/1993: «b) Mientras se utilizan cascos o auriculares conectados con aparatos receptores o reproductores de sonidos.»","Art. 146 RD 137/1993: «Deberá en general estimarse ilícito el hecho de llevar o usar armas los concurrentes a establecimientos públicos y lugares de reunión, concentración, recreo o esparcimiento»","Art. 5 D219 Decret 219/1996: «Queda prohibida la tinença d''armes de foc als vigilants»","Art. 17 D219 Decret 219/1996: «ordenarà la retirada de l''arma de foc, per un període no superior a quinze dies»","Art. 25 D219 Decret 219/1996: «hauran de realitzar obligatòriament, i com a mínim dues vegades l''any, exercicis de perfeccionament en tir policíac»","Art. 10 D219 Decret 219/1996: «L''alcalde, quan així ho aconsellin circumstàncies especials, podrà concedir als membres de la seva policia local autorització excepcional per a la possessió d''una segona arma de foc curta»","Art. 5 RD 137/1993: «a) Las armas de fuego cortas semiautomáticas de percusión central cuya capacidad de carga sea superior a veintiún cartuchos, incluido el alojado en la recámara.»","Art. 8 D219 Decret 219/1996: «d''una pistola semiautomàtica del calibre 9 mm parabellum amb una longitud de canó entre 7 i 12,5 cm»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, (select id from public.sources where url = 'https://portaljuridic.gencat.cat/ca/document-del-pjur/?documentId=129214'), 'https://portaljuridic.gencat.cat/ca/document-del-pjur/?documentId=129214', null, null, null, 'Otras normas citadas: RD 137/1993 (https://www.boe.es/buscar/act.php?id=BOE-A-1993-6202)'
  from public.topics t where t.slug = 'gub-t32-armes'
