insert into public.sources (title, url, kind, publisher, published_on) values ('Ley Orgánica 5/2000, de 12 de enero, reguladora de la responsabilidad penal de los menores (texto consolidado, BOE)', 'https://www.boe.es/buscar/act.php?id=BOE-A-2000-641', 'boe'::public.source_kind, 'Agencia Estatal Boletín Oficial del Estado', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('gub-t33-menors', 'Tema 33. Llei orgànica 5/2000: responsabilitat penal i detenció de menors') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('guardia-urbana-barcelona') and t.slug = 'gub-t33-menors' on conflict do nothing;
insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'ca', '[{"n":"1","title":"Àmbit d''aplicació de la LO 5/2000"},{"n":"2","title":"Menors de catorze anys i bases de la responsabilitat"},{"n":"3","title":"Mesures i durada"},{"n":"4","title":"Detenció de menors: drets i terminis"},{"n":"5","title":"Desistiment i drets de les víctimes"}]'::jsonb, '["Art. 1 LO 5/2000: «Esta Ley se aplicará para exigir la responsabilidad de las personas mayores de catorce años y menores de dieciocho»","Art. 17 LO 5/2000: «dentro del plazo máximo de veinticuatro horas, el menor detenido deberá ser puesto en libertad o a disposición del Ministerio Fiscal»","Art. 3 LO 5/2000: «no se le exigirá responsabilidad con arreglo a la presente Ley, sino que se le aplicará lo dispuesto en las normas sobre protección de menores previstas en el Código Civil»","Art. 17 LO 5/2000: «los menores deberán hallarse custodiados en dependencias adecuadas y separadas de las que se utilicen para los mayores de edad»","Art. 17 LO 5/2000: «También deberán notificar inmediatamente el hecho de la detención y el lugar de la custodia a los representantes legales del menor y al Ministerio Fiscal.»","Art. 7 LO 5/2000: «a) Internamiento en régimen cerrado.»","Art. 17 LO 5/2000: «Toda declaración del detenido, se llevará a cabo en presencia de su letrado y de aquéllos que ejerzan la patria potestad, tutela o guarda del menor»","Art. 17 LO 5/2000: «En defecto de estos últimos la declaración se llevará a cabo en presencia del Ministerio Fiscal, representado por persona distinta del instructor del expediente.»","Art. 17 LO 5/2000: «éste habrá de resolver, dentro de las cuarenta y ocho horas a partir de la detención»","Art. 5 LO 5/2000: «Las edades indicadas en el articulado de esta Ley se han de entender siempre referidas al momento de la comisión de los hechos»","Art. 17 LO 5/2000: «El menor detenido tendrá derecho a la entrevista reservada con su abogado con anterioridad y al término de la práctica de la diligencia de toma de declaración.»","Art. 18 LO 5/2000: «cuando los hechos denunciados constituyan delitos menos graves sin violencia o intimidación en las personas o faltas»","Art. 18 LO 5/2000: «cuando conste que el menor ha cometido con anterioridad otros hechos de la misma naturaleza, el Ministerio Fiscal deberá incoar el expediente»","Art. 17 LO 5/2000: «cuando el menor tuviera su residencia habitual fuera de España o cuando así lo solicitaran el propio menor o sus representantes legales»","Art. 9 LO 5/2000: «sólo se podrán imponer las medidas de libertad vigilada hasta un máximo de seis meses»","Art. 17 LO 5/2000: «El Juez competente para el procedimiento de hábeas corpus en relación a un menor será el Juez de Instrucción del lugar en el que se encuentre el menor privado de libertad»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2000-641'), 'https://www.boe.es/buscar/act.php?id=BOE-A-2000-641', null, null, null, null
  from public.topics t where t.slug = 'gub-t33-menors'
on conflict (topic_id, locale) do update
   set outline = excluded.outline, key_ideas = excluded.key_ideas, glossary = excluded.glossary,
