insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'ca', '[{"n":"1","title":"Taxes d''alcohol"},{"n":"2","title":"Proves de detecció alcohòlica"},{"n":"3","title":"Obligacions del conductor: atenció i dispositius"},{"n":"4","title":"Límits de velocitat en vies urbanes"},{"n":"5","title":"Elements de protecció: casc"},{"n":"6","title":"Prioritat dels vianants i ordre de preferència dels senyals"}]'::jsonb, '["Art. 20 RGC: «con una tasa de alcohol en sangre superior a 0,5 gramos por litro, o de alcohol en aire espirado superior a 0,25 miligramos por litro»","Art. 50 RGC: «b) 30 km/h en vías de un único carril por sentido de circulación.»","Art. 133 RGC: «a) Señales y órdenes de los agentes de la autoridad encargados de la vigilancia del tráfico en el ejercicio de las funciones que tengan encomendadas.»","Art. 18 RGC: «Queda prohibido conducir utilizando cualquier tipo de casco de audio, auriculares o instrumentos similares conectados a aparatos receptores o reproductores de sonido»","Art. 121 RGC: «gozarán de prioridad de paso y estancia en las vías públicas, en los términos que se regulan en el presente reglamento»","Art. 20 RGC: «Los conductores de cualquier vehículo no podrán superar la tasa de alcohol en sangre de 0,3 gramos por litro ni de alcohol en aire espirado de 0,15 miligramos por litro durante los dos años siguientes a la obtención del permiso»","Art. 20 RGC: «No podrán circular por las vías objeto de la legislación sobre tráfico, circulación de vehículos a motor y seguridad vial los conductores de vehículos ni los conductores de bicicletas»","Art. 23 RGC: «que entre la realización de la primera y de la segunda prueba medie un tiempo mínimo de 10 minutos»","Art. 23 RGC: «aún sin alcanzar estos límites, presentara la persona examinada síntomas evidentes de encontrarse bajo la influencia de bebidas alcohólicas»","Art. 22 RGC: «consistirán, normalmente, en la verificación del aire espirado mediante etilómetros que, oficialmente autorizados, determinarán de forma cuantitativa el grado de impregnación alcohólica»","Art. 50 RGC: «los vehículos que transporten mercancías peligrosas circularán como máximo a 40 km/h»","Art. 50 RGC: «Excepcionalmente, la Autoridad Municipal podrá aumentar la velocidad en vías de un único carril por sentido hasta una velocidad máxima de 50 km/h, previa señalización específica.»","Art. 118 RGC: «siendo obligatorio su uso por los menores de dieciséis años en todo tipo de vías»","Art. 118 RGC: «Los conductores que desarrollen su actividad profesional circulando en bicicletas y demás ciclos, están obligados a utilizar adecuadamente abrochado casco de protección homologado o certificado en vías urbanas y travesías.»","Art. 118 RGC: «c) Calzado cerrado, que cubra todo el pie, cuando circulen en todo tipo de vías.»","Art. 20 RGC: «los conductores no podrán hacerlo con una tasa de alcohol en sangre superior a 0,3 gramos por litro, o de alcohol en aire espirado superior a 0,15 miligramos por litro»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2003-23514'), 'https://www.boe.es/buscar/act.php?id=BOE-A-2003-23514', null, null, null, null
  from public.topics t where t.slug = 'gub-t36-reglament-circulacio'
