insert into public.sources (title, url, kind, publisher, published_on) values ('Escola d''Administració Pública de Catalunya (EAPC). Curs de prevenció de riscos laborals, Unitat 24. Primers auxilis (pàgina citada al tema 38 del temari). Extracte literal', 'https://formaciooberta.eapc.gencat.cat/contingutsdelscursos/prl/bloc5/024.html', 'web_oficial'::public.source_kind, 'Generalitat de Catalunya · Escola d''Administració Pública de Catalunya', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('gub-t38-primers-auxilis', 'Tema 38. Primers auxilis') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('guardia-urbana-barcelona') and t.slug = 'gub-t38-primers-auxilis' on conflict do nothing;
insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'ca', '[{"n":"1","title":"Concepte i finalitat dels primers auxilis"},{"n":"2","title":"Conducta PAS i trucada al 112"},{"n":"3","title":"Suport vital bàsic i DEA"},{"n":"4","title":"Obstrucció de la via aèria"},{"n":"5","title":"Ferides, hemorràgies i cremades"},{"n":"6","title":"Lesions traumatològiques, intoxicacions i altres situacions"}]'::jsonb, '["24.6 EAPC, Unitat 24. Primers auxilis: «La seguretat de la persona que presta l''ajuda és sempre la primera prioritat.»","24.6 EAPC, Unitat 24. Primers auxilis: «No donar aigua o líquids a la persona accidentada si està inconscient.»","24.10 EAPC, Unitat 24. Primers auxilis: «Refredar la zona afectada amb aigua corrent tèbia-freda durant almenys 10 minuts»","24.9 EAPC, Unitat 24. Primers auxilis: «Aplicar pressió directa sobre la ferida amb una gasa o un drap net.»","24.7 EAPC, Unitat 24. Primers auxilis: «Els DEA estan dissenyats perquè puguin ser utilitzats per persones no sanitàries.»","24.1 EAPC, Unitat 24. Primers auxilis: «Emergència mèdica: situació amb risc vital imminent que requereix una actuació urgent i l’activació immediata dels serveis d’emergència»","24.8 EAPC, Unitat 24. Primers auxilis: «En un adult o infant gran conscient, aplicar fins a cinc cops interescapulars.»","24.8 EAPC, Unitat 24. Primers auxilis: «aplicar fins a cinc compressions abdominals (maniobra de Heimlich)»","24.7 EAPC, Unitat 24. Primers auxilis: «és preferible iniciar immediatament les compressions toràciques (RCP només amb les mans)»","24.10 EAPC, Unitat 24. Primers auxilis: «en cas de cremades químiques s''ha de retirar tota la roba impregnada»","24.10 EAPC, Unitat 24. Primers auxilis: «Abans de tocar la persona electrocutada, cal tallar el corrent.»","24.11 EAPC, Unitat 24. Primers auxilis: «no només s''ha d''immobilitzar el focus de fractura, sinó també les articulacions que estan immediatament per sobre i per sota»","24.13 EAPC, Unitat 24. Primers auxilis: «no s''ha d''intentar mai sostenir-la ni impedir les convulsions»","24.12 EAPC, Unitat 24. Primers auxilis: «No provocar el vòmit, ja que en molts casos pot empitjorar la situació»","24.4 EAPC, Unitat 24. Primers auxilis: «Tots els centres de treball amb més de 50 treballadors (o 25 si així ho estableix l''autoritat laboral)»","24.11 EAPC, Unitat 24. Primers auxilis: «Luxació: és el desplaçament d''un os d''una articulació fora de la seva posició correcta.»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, (select id from public.sources where url = 'https://formaciooberta.eapc.gencat.cat/contingutsdelscursos/prl/bloc5/024.html'), 'https://formaciooberta.eapc.gencat.cat/contingutsdelscursos/prl/bloc5/024.html', null, null, null, null
  from public.topics t where t.slug = 'gub-t38-primers-auxilis'
